 for p in["bounds.md","controller-initial.rs","prepare-initial.log"]{source.push(r(p));}fs::copy(r("bounds.md"),art.join("bounds.md")).unwrap();let src=archive(&source,&art.join("source.json.gz"));let rec=archive(&files(&r("runs")),&art.join("receipts.json.gz"));let metadata=archive(&[r("jobs.json"),r("plan.json"),r("rows.json")],&art.join("observations-and-plan.json.gz"));save(art.join("archive-review.json"),&json!({"source":src,"receipts":rec,"metadata":metadata}));let raw=files(&r("perf")).into_iter().chain(files(&r("stat"))).map(|p|(p.display().to_string(),hash(&p))).collect::<BTreeMap<_,_>>();save(art.join("raw-local-pins.json"),&json!(raw));
